<script setup lang="ts">
import { computed } from 'vue'
import { useAppStore } from '@/stores/app'
import { TrendingUp, CheckCircle2, CircleDashed, Activity } from 'lucide-vue-next'
import { statusLabels } from '@/types'
import type { TaskStatus } from '@/types'
const store = useAppStore()
const statuses: { key: TaskStatus; color: string }[] = [
  { key: 'todo', color: '#9c92a9' }, { key: 'in_progress', color: '#6e61f5' }, { key: 'review', color: '#f0b65d' }, { key: 'done', color: '#52c9a7' }
]
const percent = (count: number, total: number) => total ? Math.round(count / total * 100) : 0
const stats = computed(() => statuses.map(s => ({ ...s, count: store.tasks.filter(t => t.status === s.key).length })))
</script>
<template><section><div class="page-heading"><div><h1>Thống kê hiệu suất</h1><p>Tổng hợp và phân tích tiến độ các công việc trong không gian của bạn.</p></div></div><div class="dashboard-stats"><div class="card-panel overview-stat"><span class="overview-icon purple"><Activity :size="20" /></span><p>Tổng công việc</p><strong>{{ store.tasks.length }}</strong><small>Tất cả dự án</small></div><div class="card-panel overview-stat"><span class="overview-icon green"><CheckCircle2 :size="20" /></span><p>Hoàn thành</p><strong>{{ store.completedCount }}</strong><small>Đầu việc đã xong</small></div><div class="card-panel overview-stat"><span class="overview-icon cyan"><CircleDashed :size="20" /></span><p>Còn lại</p><strong>{{ store.pendingCount }}</strong><small>Đang theo dõi</small></div><div class="card-panel overview-stat"><span class="overview-icon yellow"><TrendingUp :size="20" /></span><p>Tỉ lệ hoàn thành</p><strong>{{ store.donePercentage }}%</strong><small>Trên toàn hệ thống demo</small></div></div><div class="dashboard-columns"><div class="card-panel content-panel"><div class="content-section-title"><div><h2>Phân bố trạng thái</h2><p>Tỉ lệ công việc theo từng giai đoạn.</p></div></div><div class="chart-stack"><div v-for="s in stats" :key="s.key"><div class="bar-chart-label"><span>{{ statusLabels[s.key] }}</span><span>{{ s.count }} ({{ percent(s.count, store.tasks.length) }}%)</span></div><div class="chart-track"><div :style="{ width: `${percent(s.count, store.tasks.length)}%`, background: s.color }"></div></div></div></div></div><div class="card-panel content-panel"><div class="content-section-title"><div><h2>Tiến độ theo dự án</h2><p>Số lượng công việc hoàn thành trong mỗi dự án.</p></div></div><div class="chart-stack"><div v-for="p in store.projects" :key="p.projectId"><div class="bar-chart-label"><span>{{ p.projectName }}</span><span>{{ store.tasks.filter(t => t.projectId === p.projectId && t.status === 'done').length }}/{{ store.tasks.filter(t => t.projectId === p.projectId).length }}</span></div><div class="chart-track"><div :style="{ width: `${percent(store.tasks.filter(t => t.projectId === p.projectId && t.status === 'done').length, store.tasks.filter(t => t.projectId === p.projectId).length)}%`, background: p.color }"></div></div></div></div></div></div></section></template>
